mapper.select:
SELECT id, conversation_id, message_id, role, content,
       token_count, metadata_json, feedback, created_at
FROM t_message
WHERE conversation_id = #{conversationId}
ORDER BY created_at DESC
LIMIT #{size} OFFSET #{offset}

SELECT id, conversation_id, message_id, role, content,
       token_count, metadata_json, feedback, created_at
FROM t_message
WHERE conversation_id = #{conversationId}
  AND created_at < (
      SELECT created_at FROM t_message WHERE message_id = #{beforeMessageId}
  )
ORDER BY created_at DESC
LIMIT #{size}

mapper.update:
UPDATE t_message SET feedback = #{feedback, jdbcType=VARCHAR}
, metadata_json = CASE WHEN metadata_json IS NULL OR metadata_json = '' THEN metadata_json ELSE JSON_REMOVE(metadata_json, '$.feedbackReason') END
, metadata_json = JSON_SET(IFNULL(metadata_json, '{}'), '$.feedbackReason', #{reason})
WHERE message_id = #{messageId}
